using System.Collections;
using System.Text;
using Mythosia.Integrity;
using Mythosia.Integrity.CRC;
using Xunit;

namespace Mythosia.Test.Integrity;

[Collection(IntegrityTestCollection.Name)]
public sealed class Crc64Tests
{
    private const int BufferSize = 64 * 1024;
    private static readonly byte[] CheckInput = Encoding.ASCII.GetBytes("123456789");

    public static IEnumerable<object[]> AwsVectors()
    {
        // Frozen uint64 answers, not serialized digest octets. No value is
        // generated by the implementation or taken from NVMe document examples.
        // https://github.com/awslabs/aws-checksums/blob/12cd22e81543b8547132762023076ab6afa25559/tests/crc64_test.c#L11-L23
        yield return new object[] { CheckInput, 0xAE8B14860A799888UL };
        yield return new object[] { new byte[32], 0xCF3473434D4ECF3BUL };
        yield return new object[] { Enumerable.Range(0, 32).Select(i => (byte)i).ToArray(), 0xB9D9D4A8492CBD7FUL };
    }

    [Theory]
    [MemberData(nameof(AwsVectors))]
    public async Task AwsFixedAnswersCalibrateOracleAndAllCalculationPaths(byte[] input, ulong expected)
    {
        Assert.Equal(expected, Crc64Reference.Compute(input));
        Assert.Equal(expected, input.CRC64(CRC64Type.NVME));
        Assert.Equal(NativeBytes(expected), new CRC64(CRC64Type.NVME).Compute(input));
        var accumulator = new CRC64Accumulator(CRC64Type.NVME);
        foreach (byte value in input)
            accumulator.Append(new[] { value });
        Assert.Equal(expected, accumulator.GetCurrentValue());
        using var sync = new ObservedStream(input, asynchronous: false, chunkSize: 3);
        using var asyncSource = new ObservedStream(input, asynchronous: true, chunkSize: 3);
        Assert.Equal(expected, sync.ComputeCRC64(CRC64Type.NVME));
        Assert.Equal(expected, await asyncSource.ComputeCRC64Async(CRC64Type.NVME));
    }

    [Fact]
    public void EveryOneAndTwoByteInputMatchesOracleWholeAndSplit()
    {
        var detector = new CRC64();
        var accumulator = new CRC64Accumulator();
        for (int length = 1; length <= 2; length++)
        {
            var input = new byte[length];
            int lastValue = length == 1 ? byte.MaxValue : ushort.MaxValue;
            for (int value = 0; value <= lastValue; value++)
            {
                input[0] = (byte)(length == 1 ? value : value >> 8);
                if (length == 2) input[1] = (byte)value;
                ulong expected = Crc64Reference.Compute(input);
                Assert.Equal(expected, input.CRC64());
                Assert.Equal(NativeBytes(expected), detector.Compute(input));
                accumulator.Reset();
                accumulator.Append(input.AsSpan(0, 1));
                accumulator.Append(ReadOnlySpan<byte>.Empty);
                accumulator.Append(input.AsSpan(1));
                Assert.Equal(expected, accumulator.GetCurrentValue());
            }
        }
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(7)]
    [InlineData(8)]
    [InlineData(9)]
    [InlineData(255)]
    [InlineData(256)]
    [InlineData(257)]
    [InlineData(65535)]
    [InlineData(65536)]
    [InlineData(65537)]
    [InlineData(131089)]
    public async Task RepresentativeLengthsAndBufferBoundariesMatchIndependentCalculation(int length)
    {
        byte[] input = BinaryInput(length);
        ulong expected = Crc64Reference.Compute(input);
        Assert.Equal(expected, input.CRC64());
        var random = new Random(0x64C0 + length);
        var accumulator = new CRC64Accumulator();
        for (int offset = 0; offset < length;)
        {
            int count = Math.Min(random.Next(1, 4097), length - offset);
            accumulator.Append(input.AsSpan(offset, count));
            offset += count;
        }
        Assert.Equal(expected, accumulator.GetCurrentValue());
        using var sync = new ObservedStream(input, asynchronous: false, chunkSize: BufferSize);
        using var asyncSource = new ObservedStream(input, asynchronous: true, chunkSize: BufferSize);
        Assert.Equal(expected, sync.ComputeCRC64());
        Assert.Equal(expected, await asyncSource.ComputeCRC64Async());
    }

    [Theory]
    [InlineData(9)]
    [InlineData(257)]
    public void EveryTwoChunkSplitIncludingEmptyEdgesMatchesIndependentAnswer(int length)
    {
        byte[] input = BinaryInput(length);
        ulong expected = Crc64Reference.Compute(input);
        var accumulator = new CRC64Accumulator();
        for (int split = 0; split <= length; split++)
        {
            accumulator.Reset();
            accumulator.Append(input.AsSpan(0, split));
            accumulator.Append(input.AsSpan(split));
            Assert.Equal(expected, accumulator.GetCurrentValue());
        }
    }

    [Fact]
    public void EveryPartitionOfSmallBinaryInputsMatchesIndependentAnswer()
    {
        var accumulator = new CRC64Accumulator();
        for (int length = 1; length <= 8; length++)
        foreach (byte[] input in new[] { new byte[length], Enumerable.Repeat((byte)0xFF, length).ToArray(), BinaryInput(length) })
        {
            ulong expected = Crc64Reference.Compute(input);
            for (int boundaries = 0; boundaries < 1 << (length - 1); boundaries++)
            {
                accumulator.Reset();
                int start = 0;
                for (int end = 1; end <= length; end++)
                {
                    if (end < length && (boundaries & (1 << (end - 1))) == 0) continue;
                    accumulator.Append(input.AsSpan(start, end - start));
                    accumulator.Append(ReadOnlySpan<byte>.Empty);
                    start = end;
                }
                Assert.Equal(expected, accumulator.GetCurrentValue());
            }
        }
    }

    [Fact]
    public void AccumulatorSnapshotsEmptyChunksSlicesAndResetPreserveCorrectState()
    {
        var accumulator = new CRC64Accumulator();
        Assert.Equal(0UL, accumulator.GetCurrentValue());
        byte[] input = BinaryInput(257);
        int offset = 0;
        foreach (int count in new[] { 1, 63, 64, 65, 64 })
        {
            byte[] guarded = Enumerable.Repeat((byte)0xEE, count + 12).ToArray();
            input.AsSpan(offset, count).CopyTo(guarded.AsSpan(5));
            byte[] unchanged = guarded.ToArray();
            accumulator.Append(guarded.AsSpan(5, count));
            Assert.Equal(unchanged, guarded);
            Array.Fill(guarded, (byte)0);
            offset += count;
            ulong expected = Crc64Reference.Compute(input.AsSpan(0, offset));
            Assert.Equal(expected, accumulator.GetCurrentValue());
            Assert.Equal(expected, accumulator.GetCurrentValue());
            accumulator.Append(default);
            Assert.Equal(expected, accumulator.GetCurrentValue());
        }
        accumulator.Reset();
        Assert.Equal(0UL, accumulator.GetCurrentValue());
        accumulator.Append(CheckInput);
        Assert.Equal(0xAE8B14860A799888UL, accumulator.GetCurrentValue());
        accumulator.Reset();
        accumulator.Reset();
        Assert.Equal(0UL, accumulator.GetCurrentValue());
    }

    [Fact]
    public void IndependentNativeEndianFramesAcceptOriginalAndRejectEverySingleBitMutation()
    {
        var detector = new CRC64();
        byte[] frame = CheckInput.Concat(NativeBytes(0xAE8B14860A799888)).ToArray();
        Assert.Equal(frame, detector.Encode(CheckInput));
        Assert.Equal(frame, CheckInput.WithCRC64());
        Assert.Equal(CheckInput, detector.Decode(frame));
        Assert.False(detector.IsError(frame));
        for (int bit = 0; bit < frame.Length * 8; bit++)
        {
            byte[] damaged = frame.ToArray();
            damaged[bit / 8] ^= (byte)(1 << (bit % 8));
            Assert.True(detector.IsError(damaged));
            Assert.Empty(detector.Decode(damaged));
        }
        for (int length = 0; length < frame.Length; length++)
        {
            Assert.True(detector.IsError(frame.Take(length)));
            Assert.Empty(detector.Decode(frame.Take(length)));
        }
        for (int length = 0; length <= sizeof(ulong); length++)
        {
            Assert.True(detector.IsError(new byte[length]));
            Assert.Empty(detector.Decode(new byte[length]));
        }
    }

    [Fact]
    public async Task DefaultTypeEmptyInputsAndInvalidArgumentsHaveExplicitContracts()
    {
        var detector = new CRC64();
        Assert.IsAssignableFrom<ErrorDetection>(detector);
        Assert.Equal(new[] { CRC64Type.NVME }, Enum.GetValues<CRC64Type>());
        Assert.Equal(CRC64Type.NVME, detector.Type);
        Assert.Equal(CRC64Type.NVME, new CRC64Accumulator().Type);
        Assert.Equal("NVME", detector.GetDetectionType());
        Assert.Equal(new byte[8], detector.Compute(Array.Empty<byte>()));
        Assert.Equal(new byte[8], detector.Encode(Array.Empty<byte>()));
        Assert.Equal(0UL, Array.Empty<byte>().CRC64());
        foreach (CRC64Type invalid in new[] { (CRC64Type)(-1), (CRC64Type)1, (CRC64Type)int.MaxValue })
        {
            Assert.Throws<ArgumentOutOfRangeException>(() => new CRC64(invalid));
            Assert.Throws<ArgumentOutOfRangeException>(() => new CRC64Accumulator(invalid));
            Assert.Throws<ArgumentOutOfRangeException>(() => CheckInput.CRC64(invalid));
            Assert.Throws<ArgumentOutOfRangeException>(() => CheckInput.WithCRC64(invalid).ToArray());
            using var source = new MemoryStream(CheckInput);
            Assert.Throws<ArgumentOutOfRangeException>(() => source.ComputeCRC64(invalid));
            await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() => source.ComputeCRC64Async(invalid));
            Assert.Equal(0, source.Position);
        }
        Assert.Throws<ArgumentNullException>(() => StreamCRCExtensions.ComputeCRC64(null!));
        await Assert.ThrowsAsync<ArgumentNullException>(() => StreamCRCExtensions.ComputeCRC64Async(null!));
    }

    [Theory]
    [InlineData("Compute")]
    [InlineData("Encode")]
    [InlineData("Decode")]
    [InlineData("IsError")]
    [InlineData("CRC64")]
    [InlineData("WithCRC64")]
    public void SequenceOperationsRejectNullAndConsumeSinglePassSourcesOnce(string operation)
    {
        Assert.Throws<ArgumentNullException>(() => CheckOperation(operation, null!));
        byte[] bytes = operation is "Decode" or "IsError"
            ? CheckInput.Concat(NativeBytes(0xAE8B14860A799888)).ToArray() : CheckInput;
        var source = new SinglePassSource(bytes);
        CheckOperation(operation, source);
        Assert.Equal(1, source.EnumeratorCount);
        Assert.Equal(1, source.DisposeCount);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task ShortNonseekableReadsUseCurrentPositionOneBoundedBufferAndLeaveOpen(bool asynchronous)
    {
        byte[] input = BinaryInput(2 * BufferSize + 17);
        using var cancellation = new CancellationTokenSource();
        using var source = new ObservedStream(input, asynchronous, chunkSize: 4093, start: 17);
        ulong expected = Crc64Reference.Compute(input.AsSpan(17));
        ulong actual = asynchronous
            ? await source.ComputeCRC64Async(cancellationToken: cancellation.Token)
            : source.ComputeCRC64();
        Assert.Equal(expected, actual);
        Assert.Equal(input.Length, source.BytesConsumed);
        Assert.True(source.ReadCalls > 2);
        Assert.Equal(BufferSize, source.Buffer!.Length);
        Assert.True(source.CanRead);
        if (asynchronous) Assert.Equal(cancellation.Token, source.LastToken);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task StreamReadFailuresPropagateAndUnreadableStreamsAreRejected(bool asynchronous)
    {
        using var source = new ObservedStream(CheckInput, asynchronous, chunkSize: 3) { FailOnRead = 2 };
        Exception actual = asynchronous
            ? await Assert.ThrowsAsync<IOException>(() => source.ComputeCRC64Async())
            : Assert.Throws<IOException>(() => source.ComputeCRC64());
        Assert.Same(source.Failure, actual);
        Assert.True(source.CanRead);
        Assert.Equal(3, source.BytesConsumed);
        using var closed = new MemoryStream(CheckInput);
        closed.Dispose();
        if (asynchronous)
            await Assert.ThrowsAsync<ArgumentException>(() => closed.ComputeCRC64Async());
        else
            Assert.Throws<ArgumentException>(() => closed.ComputeCRC64());
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task AsyncCancellationBeforeOrDuringReadingReturnsNoPartialResult(bool cancelDuringRead)
    {
        using var cancellation = new CancellationTokenSource();
        using var source = new ObservedStream(CheckInput, asynchronous: true, chunkSize: 3);
        if (cancelDuringRead) source.AfterRead = () => cancellation.Cancel();
        else cancellation.Cancel();
        OperationCanceledException error = await Assert.ThrowsAnyAsync<OperationCanceledException>(
            () => source.ComputeCRC64Async(cancellationToken: cancellation.Token));
        Assert.Equal(cancellation.Token, error.CancellationToken);
        Assert.Equal(cancelDuringRead ? 1 : 0, source.ReadCalls);
        Assert.Equal(cancelDuringRead ? 3 : 0, source.BytesConsumed);
        Assert.True(source.CanRead);
    }

    private static void CheckOperation(string operation, IEnumerable<byte> source)
    {
        var detector = new CRC64();
        byte[] expectedFrame = CheckInput.Concat(NativeBytes(0xAE8B14860A799888)).ToArray();
        switch (operation)
        {
            case "Compute": Assert.Equal(NativeBytes(0xAE8B14860A799888), detector.Compute(source)); break;
            case "Encode": Assert.Equal(expectedFrame, detector.Encode(source)); break;
            case "Decode": Assert.Equal(CheckInput, detector.Decode(source)); break;
            case "IsError": Assert.False(detector.IsError(source)); break;
            case "CRC64": Assert.Equal(0xAE8B14860A799888UL, source.CRC64()); break;
            case "WithCRC64": Assert.Equal(expectedFrame, source.WithCRC64()); break;
            default: throw new ArgumentOutOfRangeException(nameof(operation));
        }
    }

    private static byte[] NativeBytes(ulong value)
    {
        // Deliberately independent of BitConverter.GetBytes used by production.
        var bytes = new byte[8];
        for (int index = 0; index < bytes.Length; index++)
            bytes[BitConverter.IsLittleEndian ? index : bytes.Length - index - 1] = (byte)(value >> (8 * index));
        return bytes;
    }

    private static byte[] BinaryInput(int length)
    {
        var bytes = new byte[length];
        uint state = 0xC0FFEE64;
        for (int index = 0; index < length; index++)
        {
            state ^= state << 13;
            state ^= state >> 17;
            state ^= state << 5;
            bytes[index] = (byte)state;
        }
        return bytes;
    }

    private sealed class SinglePassSource(byte[] bytes) : IEnumerable<byte>
    {
        public int EnumeratorCount { get; private set; }
        public int DisposeCount { get; private set; }
        public IEnumerator<byte> GetEnumerator()
        {
            if (++EnumeratorCount != 1) throw new InvalidOperationException("Source was enumerated twice.");
            return Enumerate().GetEnumerator();
        }
        IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
        private IEnumerable<byte> Enumerate()
        {
            try { foreach (byte value in bytes) yield return value; }
            finally { DisposeCount++; }
        }
    }

    private sealed class ObservedStream(byte[] bytes, bool asynchronous, int chunkSize, int start = 0) : Stream
    {
        private bool _disposed;
        public int BytesConsumed { get; private set; } = start;
        public int ReadCalls { get; private set; }
        public byte[]? Buffer { get; private set; }
        public CancellationToken LastToken { get; private set; }
        public int FailOnRead { get; init; } = -1;
        public IOException Failure { get; } = new("Read failure.");
        public Action? AfterRead { get; set; }
        public override bool CanRead => !_disposed;
        public override bool CanSeek => false;
        public override bool CanWrite => false;
        public override long Length => throw new NotSupportedException();
        public override long Position { get => throw new NotSupportedException(); set => throw new NotSupportedException(); }
        public override int Read(byte[] buffer, int offset, int count)
        {
            Assert.False(asynchronous, "An asynchronous CRC calculation used synchronous Read.");
            return ReadCore(buffer, offset, count);
        }
        public override async Task<int> ReadAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken)
        {
            Assert.True(asynchronous, "A synchronous CRC calculation used ReadAsync.");
            LastToken = cancellationToken;
            await Task.Yield();
            cancellationToken.ThrowIfCancellationRequested();
            return ReadCore(buffer, offset, count);
        }
        private int ReadCore(byte[] buffer, int offset, int count)
        {
            Assert.True(CanRead);
            Assert.InRange(count, 1, BufferSize);
            Buffer ??= buffer;
            Assert.Same(Buffer, buffer);
            if (++ReadCalls == FailOnRead) throw Failure;
            // Poison the unused tail on every read, including EOF. Only the
            // returned byte count may be passed to the CRC accumulator.
            Array.Fill(buffer, (byte)0xE7, offset, count);
            int read = Math.Min(Math.Min(chunkSize, count), bytes.Length - BytesConsumed);
            Array.Copy(bytes, BytesConsumed, buffer, offset, read);
            BytesConsumed += read;
            AfterRead?.Invoke();
            return read;
        }
        protected override void Dispose(bool disposing) { _disposed = true; base.Dispose(disposing); }
        public override void Flush() => throw new NotSupportedException();
        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
        public override void SetLength(long value) => throw new NotSupportedException();
        public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
    }
}
